33|export const resolveBindingTemplateValue = (
34|  template: string,
35|  context: Record<string, unknown> | null | undefined,
36|  paramPaths: Record<string, string>,
37|): string =>
38|  template.replace(/\{([a-zA-Z0-9_]+)\}/g, (_match, paramName: string) => {
39|    const dataPath = paramPaths[paramName];
40|    if (!dataPath) {
41|      return '';
42|    }
43|
44|    const segments = dataPath.split('.').map((segment) => segment.trim()).filter(Boolean);
45|    let cursor: unknown = context;
46|    for (const segment of segments) {
47|      if (cursor && typeof cursor === 'object' && segment in (cursor as Record<string, unknown>)) {
48|        cursor = (cursor as Record<string, unknown>)[segment];
49|      } else {
50|        cursor = undefined;
51|        break;
52|      }
53|    }
54|
55|    return cursor === undefined || cursor === null ? '' : String(cursor);
56|  });
