157|export const resolveStoreWriteValueFromEvent = (event: Event, targetEvent: string): unknown => {
158|  const target = event.target as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement | null;
159|  switch (targetEvent) {
160|    case 'onChange':
161|    case 'onBlur':
162|      return target?.value ?? '';
163|    case 'onClick':
164|      return true;
165|    case 'onPageChange': {
166|      const customValue = (event as unknown as { target?: { value?: unknown } })?.target?.value;
167|      if (typeof customValue === 'number' && Number.isFinite(customValue)) {
168|        return customValue;
169|      }
170|      if (typeof customValue === 'string' && customValue.trim().length > 0) {
171|        const parsed = Number.parseInt(customValue, 10);
172|        return Number.isFinite(parsed) ? parsed : null;
173|      }
174|      return null;
175|    }
176|    case 'onSortChange': {
177|      const customValue = (event as unknown as { target?: { value?: unknown } })?.target?.value;
178|      if (customValue && typeof customValue === 'object') {
179|        return customValue;
180|      }
181|      return null;
182|    }
183|    default:
184|      return target?.value ?? null;
